    if (accounts.length === 0) {
        return;
    }
    // For fresh logins, always start at index 0
    const activeIndex = replaceAll
        ? 0
        : (typeof stored?.activeIndex === "number" && Number.isFinite(stored.activeIndex) ? stored.activeIndex : 0);
